    KzValue res = kz_list_new(la + lb);
    kz_list_reserve(res.as.list, la + lb);   /* the buffer is lazy: ask first */
    KzList* l = res.as.list;
    if (la) { memcpy(l->items, a.as.list->items, la * sizeof(KzValue)); l->len += la; }
    if (lb) { memcpy(l->items + l->len, b.as.list->items, lb * sizeof(KzValue)); l->len += lb; }
    return res;
